package com.primehr.performancemanagement.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import com.primehr.shared.exception.IllegalLifecycleTransitionException;import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity@Table(name="spms_plan_assignment",uniqueConstraints=@UniqueConstraint(name="uk_spms_assignment_subject",columnNames={"agency_id","cycle_id","subject_type","subject_id","form_type"}))
public class PerformancePlanAssignment extends RspAuditedEntity{
 public enum SubjectType{AREA,BUSINESS_UNIT,EMPLOYEE}public enum Status{DRAFT,ACTIVE,RETIRED}
 @Column(name="cycle_id",nullable=false,length=36)private String cycleId;@Column(name="template_version_id",nullable=false,length=36)private String templateVersionId;@Enumerated(EnumType.STRING)@Column(name="subject_type",nullable=false,length=30)private SubjectType subjectType;@Column(name="subject_id",nullable=false)private Long subjectId;@Column(name="subject_code",length=80)private String subjectCode;@Column(name="subject_name",nullable=false,length=200)private String subjectName;@Column(name="area_id")private Long areaId;@Column(name="area_name",length=200)private String areaName;@Column(name="routing_business_unit_id",nullable=false)private Long routingBusinessUnitId;@Column(name="routing_business_unit_name",nullable=false,length=200)private String routingBusinessUnitName;@Column(name="owner_employee_id",nullable=false)private Long ownerEmployeeId;@Column(name="owner_employee_no",nullable=false,length=100)private String ownerEmployeeNo;@Column(name="owner_name",nullable=false,length=300)private String ownerName;@Column(name="owner_appointment_id",nullable=false)private Long ownerAppointmentId;@Column(name="owner_job_position_id",nullable=false)private Long ownerJobPositionId;@Column(name="owner_plantilla_id",nullable=false)private Long ownerPlantillaId;@Column(name="form_type",nullable=false,length=20)private String formType;@Column(name="organization_fingerprint",nullable=false,length=64)private String organizationFingerprint;@Column(name="participant_fingerprint",nullable=false,length=64)private String participantFingerprint;@Column(name="route_fingerprint",nullable=false,length=64)private String routeFingerprint;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="activated_by",length=100)private String activatedBy;@Column(name="activated_at")private Instant activatedAt;@Column(name="retired_by",length=100)private String retiredBy;@Column(name="retired_at")private Instant retiredAt;@Column(name="transition_reason",length=1000)private String transitionReason;
 protected PerformancePlanAssignment(){}public PerformancePlanAssignment(String a,String cycle,String template,SubjectType type,Long subject,String code,String name,Long area,String areaName,Long routeUnit,String routeName,Long employee,String no,String owner,Long appointment,Long job,Long plantilla,String form,String orgFp,String participantFp,String routeFp){super(a);status=Status.DRAFT;apply(cycle,template,type,subject,code,name,area,areaName,routeUnit,routeName,employee,no,owner,appointment,job,plantilla,form,orgFp,participantFp,routeFp);}
 public void update(String cycle,String template,SubjectType type,Long subject,String code,String name,Long area,String areaName,Long routeUnit,String routeName,Long employee,String no,String owner,Long appointment,Long job,Long plantilla,String form,String orgFp,String participantFp,String routeFp){draft();apply(cycle,template,type,subject,code,name,area,areaName,routeUnit,routeName,employee,no,owner,appointment,job,plantilla,form,orgFp,participantFp,routeFp);}
 private void apply(String cycle,String template,SubjectType type,Long subject,String code,String name,Long area,String areaName,Long routeUnit,String routeName,Long employee,String no,String owner,Long appointment,Long job,Long plantilla,String form,String orgFp,String participantFp,String routeFp){cycleId=requiredText(cycle,"cycleId");templateVersionId=requiredText(template,"templateVersionId");subjectType=Objects.requireNonNull(type,"subjectType");if(subject==null||subject<1)throw new IllegalArgumentException("subjectId must be positive");subjectId=subject;subjectCode=optionalText(code);subjectName=requiredText(name,"subjectName");areaId=area;this.areaName=optionalText(areaName);if(routeUnit==null||routeUnit<1)throw new IllegalArgumentException("routingBusinessUnitId must be positive");routingBusinessUnitId=routeUnit;routingBusinessUnitName=requiredText(routeName,"routingBusinessUnitName");if(employee==null||employee<1||appointment==null||appointment<1||job==null||job<1||plantilla==null||plantilla<1)throw new IllegalArgumentException("An active owner appointment snapshot is required");ownerEmployeeId=employee;ownerEmployeeNo=requiredText(no,"ownerEmployeeNo");ownerName=requiredText(owner,"ownerName");ownerAppointmentId=appointment;ownerJobPositionId=job;ownerPlantillaId=plantilla;formType=requiredText(form,"formType");organizationFingerprint=requiredText(orgFp,"organizationFingerprint");participantFingerprint=requiredText(participantFp,"participantFingerprint");routeFingerprint=requiredText(routeFp,"routeFingerprint");}
 public void activate(String actor,String reason,Instant at){draft();activatedBy=requiredText(actor,"actor");transitionReason=requiredText(reason,"reason");activatedAt=at;status=Status.ACTIVE;}public void retire(String actor,String reason,Instant at){if(status!=Status.ACTIVE)throw new IllegalLifecycleTransitionException("Only an active assignment may be retired");retiredBy=requiredText(actor,"actor");transitionReason=requiredText(reason,"reason");retiredAt=at;status=Status.RETIRED;}private void draft(){if(status!=Status.DRAFT)throw new IllegalLifecycleTransitionException("Only a draft assignment may be edited or activated");}
 public String getCycleId(){return cycleId;}public String getTemplateVersionId(){return templateVersionId;}public SubjectType getSubjectType(){return subjectType;}public Long getSubjectId(){return subjectId;}public String getSubjectCode(){return subjectCode;}public String getSubjectName(){return subjectName;}public Long getAreaId(){return areaId;}public String getAreaName(){return areaName;}public Long getRoutingBusinessUnitId(){return routingBusinessUnitId;}public String getRoutingBusinessUnitName(){return routingBusinessUnitName;}public Long getOwnerEmployeeId(){return ownerEmployeeId;}public String getOwnerEmployeeNo(){return ownerEmployeeNo;}public String getOwnerName(){return ownerName;}public Long getOwnerAppointmentId(){return ownerAppointmentId;}public Long getOwnerJobPositionId(){return ownerJobPositionId;}public Long getOwnerPlantillaId(){return ownerPlantillaId;}public String getFormType(){return formType;}public String getOrganizationFingerprint(){return organizationFingerprint;}public String getParticipantFingerprint(){return participantFingerprint;}public String getRouteFingerprint(){return routeFingerprint;}public Status getStatus(){return status;}
}
